/// <summary>
///     The <c>AVABPJobsExecution</c> class is the execution class for <c>BP-Jobs</c>
/// </summary>
class AVABPJobsExecution
{
    // replaces class KCSBatchRun in 2009
    Args                            args;
    KCS_KBVBuildingProjectTable     kcs_KBVBuildingProjectTable;
    KCS_KBVBuildingProjectID        kcs_KBVBuildingProjectID;
    boolean                         lJobMode;
    boolean                         lCheckOnly;

    container                       companiesToProcess;
    DataAreaId                      currentDataAreaId;

    KCS_KBVBuildingProjectID        fromKCS_KBVBuildingProjectID;
    container                       processingInterval;

}

