/// <summary>
/// N.Freidenberger 16.09.2025
/// </summary>
/// <param name = "_processingInterval">_processingInterval</param>
/// <returns>parmProcessingInterval</returns>
public container parmProcessingInterval(container       _processingInterval = processingInterval)
{
    processingInterval   = _processingInterval;
    return processingInterval;
}

/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPJobsController         controller;
    AVABPJobsContract           contract;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    controller = AVABPJobsController::newFromArgs(_args);
    controller.parmLoadFromSysLastValue(NoYes::No);

    contract = controller.getDataContractObject();
    contract.parmArgs(_args);
    if(     _args
        &&  _args.record()
        &&  _args.record().RecId
        &&  _args.record().TableId == tableNum(KCS_KBVBuildingProjectTable) )
    {
        locCommon = _args.record();

        if(_args.record().TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;
        }
    }

    controller.startOperation();
}

