/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVABPJobsExecution</c> as return value
/// </returns>
public static AVABPJobsExecution newFromArgs(Args _args)
{
    AVABPJobsExecution locAVABPJobsExecution;

    locAVABPJobsExecution = new AVABPJobsExecution();
    locAVABPJobsExecution.parmArgs(_args);
    locAVABPJobsExecution.init();

    return locAVABPJobsExecution;
}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    Common  locCommon;

    if (args && args.record())
    {
        locCommon = args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            kcs_KBVBuildingProjectTable = locCommon;
            kcs_KBVBuildingProjectID    = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        }
        else
        {
            kcs_KBVBuildingProjectTable = null;
            kcs_KBVBuildingProjectID    = '';
        }

    }
}

/// <summary>
///     AVA <c>checkCompaniesToProcess</c> method.
/// </summary>
/// <param name="_companiesToProcess">
///     <c>container</c> as type
/// </param>
public void checkCompaniesToProcess(container _companiesToProcess = conNull())
{
    if(_companiesToProcess != conNull())
    {
        companiesToProcess  = _companiesToProcess;
    }
    if(companiesToProcess   == conNull())
    {
        companiesToProcess  = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    }
}

