/// <summary>
///     AVA <c>updateBPStatusCompany</c> method.
/// </summary>
public void updateBPStatusCompany()
{
    AVABPJobsUpdateStatus locAVABPJob;

    locAVABPJob = new AVABPJobsUpdateStatus();
    locAVABPJob.init();
    locAVABPJob.parmlJobMode(lJobMode);
    locAVABPJob.parmKCS_KBVBuildingProjectID(kcs_KBVBuildingProjectID);
    locAVABPJob.parmProcessingInterval(processingInterval);
    locAVABPJob.initQuery();
    locAVABPJob.run();
}

