/// <summary>
///     AVA <c>updateSalesVolume</c> method.
/// </summary>
/// <param name="_companiesToProcess">
///     <c>container</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean updateSalesVolume(container _companiesToProcess = conNull())
{
    boolean retVal;

    int i;

    this.checkCompaniesToProcess(_companiesToProcess);

    for(i = 1; i <= conlen(companiesToProcess); i++)
    {
        currentDataAreaId = conpeek(companiesToProcess, i);
        changecompany(currentDataAreaId)
        {
            this.updateSalesVolumeCompany();
        }
        retVal = true;
    }

    return retVal;
}

/// <summary>
///     AVA <c>updateSalesVolumeCompany</c> method.
/// </summary>
public void updateSalesVolumeCompany()
{
    AVABPJobsUpdateSalesVolume locAVABPJob;

    locAVABPJob = new AVABPJobsUpdateSalesVolume();
    locAVABPJob.init();
    locAVABPJob.parmlJobMode(lJobMode);
    locAVABPJob.parmKCS_KBVBuildingProjectID(kcs_KBVBuildingProjectID);
    locAVABPJob.parmKCS_KBVPotentialSalesVolType(KCS_KBVPotentialSalesVolType::CompanySpecific);
    locAVABPJob.parmUpdateKCS_KBVPotentialSalesVolumeTbl(true);
    locAVABPJob.parmlRicoSync(false);
    locAVABPJob.parmProcessingInterval(processingInterval);
    locAVABPJob.initQuery();
    locAVABPJob.run();
}

