/// <summary>
///     AVA <c>updateResponsibilities</c> method.
/// </summary>
/// <param name="_companiesToProcess">
///     <c>container</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean updateResponsibilities(container _companiesToProcess = conNull())
{
    boolean retVal;

    int     i;

    this.checkCompaniesToProcess(_companiesToProcess);

    for(i = 1; i <= conlen(companiesToProcess); i++)
    {
        currentDataAreaId = conpeek(companiesToProcess, i);
        changecompany(currentDataAreaId)
        {
            if (lCheckOnly)
            {
                ttsbegin;
                this.updateResponsibilitiesCompany();
                ttsabort;
            }
            else
            {
                this.updateResponsibilitiesCompany();
            }
        }
        retVal = true;
    }

    return retVal;
}

/// <summary>
///     AVA <c>updateResponsibilitiesCompany</c> method.
/// </summary>
public void updateResponsibilitiesCompany()
{
    AVABPJobsUpdateResponsibilities locAVABPJob;

    locAVABPJob = new AVABPJobsUpdateResponsibilities();
