/// <summary>
///     AVA <c>updateActivitiesCompany</c> method.
/// </summary>
/// <param name="_create">
///     <c>KBVActivitySendList</c> as type
/// </param>
/// <param name="_send">
///     <c>KCS_PrintMasterDataList</c> as type
/// </param>
public void updateActivitiesCompany(KBVActivitySendList _create, KCS_PrintMasterDataList _send)
{
    AVABPJobsUpdateActivities locAVABPJob;

    locAVABPJob = new AVABPJobsUpdateActivities();
    locAVABPJob.init();
    locAVABPJob.parmlJobMode(lJobMode);
    locAVABPJob.parmKCS_KBVBuildingProjectID(kcs_KBVBuildingProjectID);
    locAVABPJob.parmCreateActivities(_create);
    locAVABPJob.parmSendActivities(_send);
    locAVABPJob.parmProcessingInterval(processingInterval);
    locAVABPJob.initQuery();
    locAVABPJob.run();
}

/// <summary>
///     AVA <c>setKBVBuildingProjectIdRange</c> method.
/// </summary>
/// <param name="_query">
///     <c>Query</c> as type
/// </param>
/// <param name="_tableId">
///     <c>TableId</c> as type
/// </param>
/// <param name="_fieldId">
///     <c>FieldId</c> as type
/// </param>
/// <param name="_filterValue">
///     <c>str</c> as type
/// </param>
/// <returns>
///     <c>QueryBuildRange</c> as return value
/// </returns>
static QueryBuildRange setKBVBuildingProjectIdRange(Query   _query,
                                                    TableId _tableId,
                                                    FieldId _fieldId,
                                                    str     _filterValue = '')
{
    QueryBuildRange     qbr;

    KCS_KBVParameters   locKCS_KBVParameters;

    locKCS_KBVParameters = KCS_KBVParameters::find();
    //Filter Bauvorhaben
    qbr = SysQuery::findOrCreateRange(_query.dataSourceTable(_tableId), _fieldId);

    if(_filterValue)
    {
        qbr.value(QueryValue(_filterValue));
    }
    else if (locKCS_KBVParameters.NDX_KBVBuildingProjectIDFrom)
    {
        /*
        qbr.value(  SysQuery::range(locKCS_KBVParameters.NDX_KBVBuildingProjectIDFrom,
                                    locKCS_KBVParameters.NDX_KBVBuildingProjectIDTo     )   );
        */
        // open ended >= NDX_KBVBuildingProjectIDFrom
        qbr.value(  SysQuery::range(locKCS_KBVParameters.NDX_KBVBuildingProjectIDFrom, '')   );
    }

    return qbr;
}

/// <summary>
///     AVA <c>getCompaniesKCS_KBVBPCompanySpecific</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public static container getCompaniesKCS_KBVBPCompanySpecific(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID )
{
    container                   retVal;
    KCS_KBVBPCompanySpecific    locBuffer;

    #define.datCompany('DAT')

    if(_kcs_KBVBuildingProjectID)
    {
        while select crosscompany DataAreaId, KCS_KBVBuildingProjectID
        from        locBuffer
        group by    locBuffer.DataAreaId
        where       locBuffer.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
        {
            if (strUpr(locBuffer.DataAreaId) != #datCompany)
            {
                retVal += locBuffer.DataAreaId;
            }
        }
    }

    return retVal;
}

/// <summary>
///     AVA <c>getCompaniesKCS_KBVPotentialSalesVolumeTbl</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public static container getCompaniesKCS_KBVPotentialSalesVolumeTbl(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID )
{
    container                       retVal;
    KCS_KBVPotentialSalesVolumeTbl  locBuffer;

    if(_kcs_KBVBuildingProjectID)
    {
        select firstonly DataAreaId, KCS_KBVBuildingProjectID
        from    locBuffer
        where   locBuffer.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID;

        if(locBuffer.RecId)
        {
            retVal = [locBuffer.DataAreaId];
        }
        else
        {
            retVal = [curext()];
        }
    }

    return retVal;
}

/// <summary>
///     AVA <c>getCompaniesKCS_KBVPotentialSalesVolumeGLB</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public static container getCompaniesKCS_KBVPotentialSalesVolumeGLB(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID )
{
    container                       retVal;
    KCS_KBVPotentialSalesVolumeTbl  locBuffer;

    #define.datCompany('DAT')

    if(_kcs_KBVBuildingProjectID)
    {
        while select crosscompany DataAreaId, KCS_KBVBuildingProjectID
        from        locBuffer
        group by    locBuffer.DataAreaId
        where       locBuffer.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
        {
            if (strUpr(locBuffer.DataAreaId) != #datCompany)
            {
                retVal += locBuffer.DataAreaId;
            }
        }
    }

    if(retVal == conNull())
    {
        retVal = [curext()];
    }

    return retVal;
}
